    sell_signal = (rsi > 70) & (k > 80) & (data['Close'] < ma)

    data['Buy'] = np.where(buy_signal, 1, 0)
    data['Sell'] = np.where(sell_signal, 1, 0)

    return data

def stop_loss_trailing(data, percentage):
    data['Stop Loss'] = data['Close'] * (1 - percentage/100)
    return data

def position_sizing(data, percentage):
